;padding-top:12px;font-size:11px;line-height:1.9;color:#87947f}summary{cursor:pointer;font-size:12px;font-weight:700;color:#6c8468}.history-scroll{overflow-x:auto}table{border-collapse:collapse;min-width:520px;width:100%;font-size:11px;margin-top:12px;text-align:right}td,th{padding:10px 8px;border-bottom:1px solid #edf0e8}th:first-child,td:first-child{text-align:left}td small{display:block;color:#97a38f}.tracking-summary{margin-top:20px}@media(max-width:650px){.remaining-panel{margin:15px 12px;padding:16px}.remaining-probabilities{gap:6px}.remaining-probabilities>div{padding:12px 5px}.remaining-probabilities strong{font-size:23px}.remaining-probabilities small{font-size:10px}.remaining-probabilities span{font-size:9px}}
